<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoDatosLaborales, descargarSustentoContrato, guardarDatosLaborales, listarDatosLaborales, listarOpcionesDatosLaborales } from '../services/datosLaborales'
import type { CatalogoOption, DatosLaborales, DatosLaboralesPayload, PersonaOption } from '../interfaces/datosLaborales.interface'
const rows=ref<DatosLaborales[]>([]),personas=ref<PersonaOption[]>([]),regimenes=ref<CatalogoOption[]>([]),afps=ref<CatalogoOption[]>([]),bancos=ref<CatalogoOption[]>([]),criterio=ref(''),page=ref(1),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const defaults:DatosLaboralesPayload={persona_id:0,codigo_trabajador:'',regimen_id:0,afp_id:null,banco_id:null,nro_cuenta_ahorros:null,nro_contrato:null,fecha_contrato:null,nro_cuspp:null,fecha_ingreso:'',fecha_cese:null,sueldo_base:0,sustento_contrato:null};const form=reactive<DatosLaboralesPayload>({...defaults});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function options(){try{const r=await listarOpcionesDatosLaborales();personas.value=r.personas;regimenes.value=r.regimenes;afps.value=r.afps;bancos.value=r.bancos}catch(v){error.value=message(v)}}
async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const r=await listarDatosLaborales(criterio.value,page.value);rows.value=r.data;total.value=r.total;page.value=r.current_page;lastPage.value=r.last_page}catch(v){error.value=message(v)}finally{loading.value=false}}
function openCreate(){editing.value=null;Object.assign(form,defaults);error.value='';modal.value=true}
function openEdit(x:DatosLaborales){editing.value=x.id;Object.assign(form,{persona_id:x.persona_id,codigo_trabajador:x.codigo_trabajador,regimen_id:x.regimen_id,afp_id:x.afp_id,banco_id:x.banco_id,nro_cuenta_ahorros:x.nro_cuenta_ahorros,nro_contrato:x.nro_contrato,fecha_contrato:x.fecha_contrato?.slice(0,10)??null,nro_cuspp:x.nro_cuspp,fecha_ingreso:x.fecha_ingreso?.slice(0,10)??'',fecha_cese:x.fecha_cese?.slice(0,10)??null,sueldo_base:Number(x.sueldo_base),sustento_contrato:null});error.value='';modal.value=true}
function fileSelected(e:Event){form.sustento_contrato=(e.target as HTMLInputElement).files?.[0]??null}
function validate(){const today=new Date().toISOString().slice(0,10);if(!form.persona_id)return 'Debe seleccionar una persona.';if(form.codigo_trabajador.trim().length<2)return 'El código debe tener entre 2 y 20 caracteres.';if(!form.regimen_id)return 'Debe seleccionar un régimen.';if(!form.fecha_ingreso)return 'La fecha de ingreso es obligatoria.';if(form.fecha_ingreso>today)return 'La fecha de ingreso no puede ser futura.';if(form.fecha_cese&&form.fecha_cese<=form.fecha_ingreso)return 'La fecha de cese debe ser posterior al ingreso.';if(!Number.isFinite(form.sueldo_base)||form.sueldo_base<0)return 'El sueldo base no es válido.';if(form.sustento_contrato&&(form.sustento_contrato.type!=='application/pdf'||form.sustento_contrato.size>5*1024*1024))return 'El sustento debe ser un PDF de máximo 5 MB.';return ''}
async function save(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarDatosLaborales(editing.value,{...form,codigo_trabajador:form.codigo_trabajador.trim().toUpperCase(),nro_cuenta_ahorros:form.nro_cuenta_ahorros?.trim()||null,nro_contrato:form.nro_contrato?.trim()||null,nro_cuspp:form.nro_cuspp?.trim()||null});modal.value=false;success.value=`Datos laborales ${editing.value?'actualizados':'registrados'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(x:DatosLaborales){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} al trabajador ${x.codigo_trabajador}?`))return;try{const r=await cambiarEstadoDatosLaborales(x.id);x.estado=r.estado;success.value=r.message??`Trabajador ${r.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
async function download(x:DatosLaborales){try{await descargarSustentoContrato(x.id,x.codigo_trabajador)}catch(v){error.value=message(v)}}
function move(v:number){if(v<1||v>lastPage.value)return;page.value=v;load()}const label=(x:CatalogoOption|null|undefined)=>x?`${x.codigo} · ${x.descripcion??x.nombre??''}`:'—';const date=(v:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'—';onMounted(()=>Promise.all([options(),load()]))
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Datos laborales</nav><header class="hero"><div class="mark">DL</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Datos laborales</h1><p>Contratos, régimen, previsión, cuenta bancaria e información remunerativa.</p></div><strong>{{total}} registros</strong></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><form @submit.prevent="load(true)"><label>Buscar trabajador<input v-model.trim="criterio" placeholder="Código, nombre, apellidos o DNI"></label><button>Buscar</button><button v-if="criterio" type="button" class="soft" @click="criterio='';load(true)">Limpiar</button><button type="button" class="new" @click="openCreate">Registrar trabajador</button></form></section><section class="table-card"><header><small>REGISTROS CONTRACTUALES</small><h2>Información laboral</h2></header><div v-if="loading" class="empty">Consultando datos laborales…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros.</div><div v-else class="scroll"><table><thead><tr><th>Código / trabajador</th><th>Régimen</th><th>AFP / CUSPP</th><th>Banco / cuenta</th><th>Contrato</th><th>Ingreso / cese</th><th>Sueldo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.codigo_trabajador}}</b><small>{{x.persona?.nombre_completo??`Persona #${x.persona_id}`}}</small><small>DNI: {{x.persona?.dni||'—'}}</small></td><td>{{label(x.regimen)}}</td><td>{{label(x.afp)}}<small>CUSPP: {{x.nro_cuspp||'—'}}</small></td><td>{{label(x.banco)}}<small>{{x.nro_cuenta_ahorros||'Sin cuenta'}}</small></td><td>{{x.nro_contrato||'—'}}<small>{{date(x.fecha_contrato)}}</small><button v-if="x.sustento_contrato" class="link" @click="download(x)">Descargar sustento</button></td><td>{{date(x.fecha_ingreso)}}<small>Cese: {{date(x.fecha_cese)}}</small></td><td>S/ {{Number(x.sueldo_base).toLocaleString('es-PE',{minimumFractionDigits:2})}}</td><td><span :class="x.estado?'active':'inactive'">{{x.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="openEdit(x)">Editar</button><button :class="x.estado?'disable':'enable'" @click="toggle(x)">{{x.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="move(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="move(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">DL</div><div><small>{{editing?'ACTUALIZAR REGISTRO':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} datos laborales</h2></div><button type="button" class="close" @click="modal=false">×</button></header><div class="grid"><label class="full">Persona *<select v-model="form.persona_id" :disabled="editing!==null"><option :value="0">Seleccione una persona</option><option v-for="x in personas" :key="x.id" :value="x.id">{{x.nombre_completo}} · DNI {{x.dni||'—'}}</option></select></label><label>Código trabajador *<input v-model="form.codigo_trabajador" maxlength="20"></label><label>Régimen *<select v-model="form.regimen_id"><option :value="0">Seleccione</option><option v-for="x in regimenes" :key="x.id" :value="x.id">{{label(x)}}</option></select></label><label>AFP<select v-model="form.afp_id"><option :value="null">Sin AFP / ONP</option><option v-for="x in afps" :key="x.id" :value="x.id">{{label(x)}}</option></select></label><label>N.º CUSPP<input v-model="form.nro_cuspp" maxlength="20"></label><label>Banco<select v-model="form.banco_id"><option :value="null">Sin banco</option><option v-for="x in bancos" :key="x.id" :value="x.id">{{label(x)}}</option></select></label><label>N.º cuenta de ahorros<input v-model="form.nro_cuenta_ahorros" maxlength="50"></label><label>N.º contrato<input v-model="form.nro_contrato" maxlength="50"></label><label>Fecha de contrato<input v-model="form.fecha_contrato" type="date"></label><label>Fecha de ingreso *<input v-model="form.fecha_ingreso" type="date"></label><label>Fecha de cese<input v-model="form.fecha_cese" type="date"><small>Dejar vacío si permanece activo.</small></label><label>Sueldo base *<input v-model.number="form.sueldo_base" type="number" min="0" max="999999999999.99" step="0.01"></label><label>Sustento de contrato<input type="file" accept="application/pdf" @change="fileSelected"><small>PDF, máximo 5 MB{{editing?' · déjelo vacío para conservar el actual':''}}.</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#356ca5;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;flex:none;border-radius:10px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#eaf1f8;font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:12px;border-radius:9px;background:#fff}.filters form{display:flex;align-items:end;gap:6px}.filters label{width:min(480px,100%);margin-right:auto;font-size:.5rem}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.filters button,.table-card>footer button,.dialog footer button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.new{background:#287154!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1250px;border-collapse:collapse;font-size:.48rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left;vertical-align:middle}th{color:#fff;background:#526d79}td>b,td>small{display:block}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:4px}.actions button,.link{padding:6px 8px;border:0;border-radius:5px;font-size:.44rem}.edit{color:#2d5f92;background:#e6f0fa}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.link{display:block;padding:3px 0;color:var(--accent);background:none}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;align-items:center;justify-content:center;gap:10px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:18px;display:grid;place-items:center;background:#172b3daa}.dialog{width:min(850px,100%);max-height:94vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;align-items:center;gap:10px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.close{margin-left:auto;border:0;color:#59666c;background:none;font-size:1.3rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px 12px}.grid label{font-size:.5rem}.grid label small{display:block;margin-top:3px;color:#7e8a90}.full{grid-column:1/-1}.dialog>footer{margin-top:18px;display:flex;justify-content:flex-end;gap:7px}@media(max-width:780px){.hero,.filters form{flex-wrap:wrap}.hero>strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.full{grid-column:auto}}
</style>
